APPLE_DESIGN_CSS = r''':root{--design-system:apple-commercial;--surface:#f5f5f7;--panel:#ffffff;--panel-soft:#f0f1f3;--ink:#1d1d1f;--muted:#6e6e73;--line:#d2d2d7;--line-strong:#a1a1a6;--brand:#0071e3;--brand-ink:#0066cc;--accent:#0071e3;--ok:#34c759;--focus:#0071e3;--shadow:0 1px 2px #0000000a,0 12px 34px #00000012;--shadow-hover:0 2px 6px #0000000d,0 20px 46px #00000018;--radius-sm:10px;--radius-md:14px;--radius-lg:18px;--radius-xl:24px;--ease-out:cubic-bezier(.22,.61,.36,1)}
@media (prefers-color-scheme:dark){:root{--surface:#000000;--panel:#1d1d20;--panel-soft:#2c2c2e;--ink:#f5f5f7;--muted:#a1a1a6;--line:#38383a;--line-strong:#5a5a5e;--brand:#2997ff;--brand-ink:#64a8ff;--accent:#64d2ff;--focus:#64a8ff;--shadow:0 1px 2px #00000066,0 16px 40px #00000066;--shadow-hover:0 2px 8px #00000070,0 24px 56px #00000080}}
body{font-family:-apple-system,BlinkMacSystemFont,"SF Pro Text","SF Pro Display","Helvetica Neue","Inter","PingFang SC","Hiragino Sans GB","Microsoft YaHei",sans-serif;-webkit-font-smoothing:antialiased;text-rendering:optimizeLegibility}
body::selection{background:color-mix(in srgb,var(--brand) 22%,transparent)}
:is(a,button,input,select,summary,[tabindex]):focus-visible{outline:3px solid color-mix(in srgb,var(--focus) 58%,transparent);outline-offset:3px;border-radius:var(--radius-sm)}
@media (prefers-reduced-motion:reduce){*,*::before,*::after{scroll-behavior:auto!important;transition-duration:.01ms!important;animation-duration:.01ms!important}}
'''

APPLE_DETAIL_CSS = r'''.shell{max-width:1280px;margin:0 auto;padding:0 clamp(16px,3vw,38px) 72px}.breadcrumb{display:flex;gap:8px;align-items:center;min-height:44px;padding:16px 0 10px;color:var(--muted);font-size:12px;font-weight:500}.breadcrumb a{color:var(--brand-ink);font-weight:550;text-decoration:none}.breadcrumb a:hover{text-decoration:underline}.hero{padding:10px 0 20px;border-bottom:1px solid var(--line)}.eyebrow{display:flex;gap:8px;color:var(--brand-ink);font-size:11px;font-weight:650;letter-spacing:.14em;text-transform:uppercase}.eyebrow:before{content:"";width:18px;height:2px;border-radius:2px;background:var(--accent)}h1{margin:8px 0 9px;font-size:clamp(30px,3.6vw,42px);line-height:1.06;letter-spacing:-.04em}.description{max-width:720px;color:var(--muted);font-size:14px}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:18px 0 22px}.metric{min-height:88px;padding:15px 16px;border:1px solid var(--line);border-radius:var(--radius-lg);background:var(--panel);box-shadow:var(--shadow)}.metric span{display:block;color:var(--muted);font-size:11px;font-weight:500}.metric strong{display:block;margin-top:4px;font-size:21px;letter-spacing:-.035em}h2{margin:32px 0 13px;font-size:19px;letter-spacing:-.03em}.charts{display:grid;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));gap:14px}.chart{overflow:hidden;padding:0;border:1px solid var(--line);border-radius:var(--radius-lg);background:var(--panel);box-shadow:var(--shadow);color:var(--ink);font:inherit;text-align:left;cursor:zoom-in;transition:border-color .18s var(--ease-out),box-shadow .18s var(--ease-out)}.chart:hover{border-color:var(--line-strong);box-shadow:var(--shadow-hover)}.chart img{display:block;width:100%;height:auto;background:var(--panel-soft)}.chart span{display:block;padding:11px 13px;color:var(--brand-ink);font-size:12px;font-weight:600}.field-panel{overflow:hidden;border:1px solid var(--line);border-radius:var(--radius-lg);background:var(--panel);box-shadow:var(--shadow)}.field-table{color:var(--ink)}.field-table thead th{background:color-mix(in srgb,var(--panel) 92%,transparent);color:var(--muted);font-size:11px;font-weight:600;letter-spacing:.02em}.field-table th,.field-table td{border-top:1px solid var(--line)}.field-table tbody th,.field-table td{background:transparent}.raw-data{margin-top:14px;border:1px solid var(--line);border-radius:var(--radius-lg);background:var(--panel);color:var(--ink);box-shadow:var(--shadow)}.raw-data summary{min-height:48px;color:var(--brand-ink);font-weight:600;line-height:48px}.footer-nav{display:flex;justify-content:space-between;gap:10px;margin-top:32px}.footer-nav a{min-height:60px;padding:15px 17px;border:1px solid var(--line);border-radius:var(--radius-lg);background:var(--panel);box-shadow:var(--shadow);transition:border-color .18s var(--ease-out),box-shadow .18s var(--ease-out)}.footer-nav a:hover{border-color:var(--line-strong);box-shadow:var(--shadow-hover)}.chart-dialog{width:min(1100px,calc(100vw - 32px));max-height:calc(100vh - 32px);padding:0;border:1px solid color-mix(in srgb,var(--ink) 10%,transparent);border-radius:var(--radius-xl);background:color-mix(in srgb,var(--panel) 96%,transparent);box-shadow:0 24px 80px #00000030;backdrop-filter:saturate(180%) blur(24px)}.chart-dialog article{max-height:calc(100vh - 32px);overflow:auto;overscroll-behavior:contain}.chart-dialog header{position:sticky;top:0;z-index:1;padding:16px 18px;border-bottom:1px solid var(--line);background:color-mix(in srgb,var(--panel) 88%,transparent);backdrop-filter:blur(20px)}.chart-dialog header p{margin:0;color:var(--brand-ink);font-size:11px;font-weight:650;letter-spacing:.12em;text-transform:uppercase}.chart-dialog header h3{margin:2px 0 0;font-size:20px;letter-spacing:-.035em}.chart-dialog header button{height:36px;padding:0 14px;border:1px solid var(--line);border-radius:999px;background:var(--panel-soft);color:var(--ink);font-size:12px;font-weight:650}.chart-dialog-image{padding:16px 18px;background:var(--surface)}@media (max-width:760px){.metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.facts{grid-template-columns:1fr}.footer-nav{align-items:stretch;flex-direction:column}.footer-nav a{width:100%}.footer-nav .next{text-align:left}}@media (max-width:430px){.metrics{grid-template-columns:1fr}.chart-dialog{width:calc(100vw - 20px);max-height:calc(100vh - 20px)}}'''

APPLE_WANGQIAN_CSS = r'''.shell{max-width:1120px;margin:0 auto;padding:0 clamp(16px,3vw,36px) 66px}.breadcrumb{display:flex;gap:8px;align-items:center;min-height:44px;padding:16px 0 10px;color:var(--muted);font-size:12px}.breadcrumb a{color:var(--brand-ink);font-weight:550;text-decoration:none}.hero{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:22px;align-items:end;padding:10px 0 22px;border-bottom:1px solid var(--line)}.eyebrow{display:flex;gap:8px;color:var(--brand-ink);font-size:11px;font-weight:650;letter-spacing:.14em;text-transform:uppercase}.eyebrow:before{content:"";width:18px;height:2px;border-radius:2px;background:var(--accent)}h1{margin:8px 0 9px;font-size:clamp(30px,3.6vw,42px);line-height:1.06;letter-spacing:-.04em}.subtitle{max-width:700px;color:var(--muted);font-size:14px}.kpi{min-width:190px;min-height:112px;padding:17px;border:1px solid var(--line);border-radius:var(--radius-xl);background:var(--panel);box-shadow:var(--shadow)}.kpi span{color:var(--muted);font-size:12px;font-weight:500}.kpi strong{margin-top:3px;font-size:32px;letter-spacing:-.045em}.error{border:1px solid color-mix(in srgb,#ff3b30 20%,var(--line));border-radius:var(--radius-lg);background:color-mix(in srgb,#ff3b30 7%,var(--panel));color:#c0261c;font-weight:600}.project{overflow:hidden;margin-top:14px;border:1px solid var(--line);border-radius:var(--radius-lg);background:var(--panel);box-shadow:var(--shadow)}.project header{display:flex;justify-content:space-between;gap:12px;align-items:center;padding:15px 17px;border-bottom:1px solid var(--line);background:color-mix(in srgb,var(--panel) 88%,transparent)}.project h2{font-size:16px;letter-spacing:-.025em}.project a{color:var(--brand-ink);text-decoration:none}.project header span{color:var(--brand-ink);font-size:12px;font-weight:600}th{color:var(--muted);font-size:11px;font-weight:600}.status.sold{color:#b25000;background:color-mix(in srgb,#ff9f0a 11%,var(--panel))}@media (prefers-color-scheme:dark){.error{color:#ff9d9a}.status.sold{color:#ffb45c}}@media (max-width:760px){.hero{align-items:start;grid-template-columns:1fr}.kpi{width:100%}.project header{align-items:flex-start;flex-direction:column}}'''
